-- Page-by-page supplemental references: C9 page 2 and C18 page 5.
-- The directory explicitly lists the associated engine families; entries remain reference-only.
on conflict(part_number) do update set
 name=excluded.name,
 engine_models=(select array(select distinct model_name from unnest(public.part_catalog.engine_models || excluded.engine_models) as models(model_name) order by model_name)),
 technical_group=excluded.technical_group,
 source_name=excluded.source_name,
 source_url=excluded.source_url,
 source_note=excluded.source_note,
 verification_status='REFERENCE',
 updated_at=now();

-- The public 3500 directory is a combined 3508/3512/3516 family listing.
-- Include all three family candidates, without asserting exact CB/build compatibility.
update public.part_catalog
set engine_models=(select array(select distinct model_name from unnest(engine_models || array['3508']::text[]) as models(model_name) order by model_name)),
    updated_at=now()
where source_url='https://htshco.ir/en/brands/caterpillar/parts/series/3500'
  and source_note like 'Public CAT 3508/3512/3516 family directory reference%';
